require __DIR__.'/../../includes/bootstrap.php';header('Content-Type: application/json');require_role(['admin','portaria']);if($_SERVER['REQUEST_METHOD']!=='POST')exit('{}');verify_csrf();$token=(string)($_POST['token']??'');$q=db()->prepare('SELECT a.id,a.nome,a.foto,a.qr_token,t.nome turma,(SELECT tipo FROM scp_registros_acesso r WHERE r.aluno_id=a.id ORDER BY registrado_em DESC,id DESC LIMIT 1) ultimo FROM scp_alunos a LEFT JOIN scp_turmas t ON t.id=a.turma_id WHERE a.qr_token=? AND a.ativo=1');$q->execute([$token]);$a=$q->fetch();if(!$a){echo json_encode(['ok'=>false]);exit;}$dentro=$a['ultimo']==='entrada';echo json_encode(['ok'=>true,'nome'=>$a['nome'],'foto'=>$a['foto'],'turma'=>$a['turma'],'token'=>$a['qr_token'],'dentro'=>$dentro,'sugerida'=>$dentro?'saida':'entrada']);

